if ! docker info >/dev/null 2>&1; then echo docker:unavailable; exit 0; fi
echo docker:ok
state() { s=$(docker inspect -f '{{.State.Status}}' "$1" 2>/dev/null) || { echo missing; return; }; if [ "$s" = running ]; then echo running; else echo stopped; fi; }
echo proxy:$(state kamal-proxy)
echo db:$(state 'shipkit-probe-db')
echo app:$(docker ps -a -q --filter 'label=service=shipkit-probe' | wc -l | tr -d ' ')
echo arch:$(docker info --format '{{.Architecture}}' 2>/dev/null)

docker exec -i shipkit-probe-db psql -U postgres -d probe -v ON_ERROR_STOP=1 -tA <<'SHIPKIT_SQL'
SELECT "MigrationId" FROM "__EFMigrationsHistory" ORDER BY "MigrationId" DESC LIMIT 1;
SHIPKIT_SQL
